import { readFileSync } from 'node:fs';
import { Client } from 'ssh2';

const conn = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const cmd = process.argv[3];
const REQUIRED_IP = '51.79.226.200';

function run(client, command) {
  return new Promise((resolve, reject) => {
    client.exec(command, (err, stream) => {
      if (err) return reject(err);
      let out = '', errout = '';
      stream.on('close', (code) => resolve({ code, out, errout }));
      stream.on('data', (d) => (out += d));
      stream.stderr.on('data', (d) => (errout += d));
    });
  });
}

const client = new Client();
client.on('ready', async () => {
  try {
    // SAFETY ASSERT: confirm we are on the LIVE .200 box before anything else
    const hn = await run(client, 'hostname -I');
    if (!hn.out.includes(REQUIRED_IP)) {
      console.error('SAFETY ABORT: hostname -I does not contain ' + REQUIRED_IP + ' -> ' + hn.out.trim());
      client.end();
      process.exit(2);
    }
    const r = await run(client, cmd);
    process.stdout.write(r.out);
    if (r.errout) process.stderr.write('\n[STDERR]\n' + r.errout);
    client.end();
    process.exit(r.code || 0);
  } catch (e) {
    console.error('ERR', e.message);
    client.end();
    process.exit(1);
  }
});
client.on('error', (e) => { console.error('CONN ERR', e.message); process.exit(1); });
client.connect({ host: conn.host, port: conn.port, username: conn.username, password: conn.password, readyTimeout: 15000 });

